+
+            if (randomized) {
+                List<Integer> positions = new java.util.ArrayList<>(positionsStream.boxed().toList());
+                Collections.shuffle(positions, random);
+                orders[i] = positions.stream().mapToInt(x -> x).toArray();
+            } else {
+                orders[i] = positionsStream.toArray();
+            }
+        }
+
+        return orders;
+    }
