+                "cluster.max_shards_per_node": 1
+              }
+            }""");
+        assertAcknowledged(client().performRequest(updateClusterSettingsRequest));
+
+        final Response rolloverResponse = client().performRequest(new Request("POST", "/" + dataStreamName + "/_rollover?lazy"));
